#!/usr/bin/env bash
# cleanup_all_experiments.sh
# Deletes all files generated by the experiment pipeline (--experiment-id).
# Leaves production files (no suffix) untouched.
#
# Usage:
#   bash cleanup_all_experiments.sh          # dry-run (default)
#   bash cleanup_all_experiments.sh --delete # actually delete

RENDERS=~/data/renders
DRY_RUN=true
[[ "$1" == "--delete" ]] && DRY_RUN=false

AXIS_EXPS=(axis_v00 axis_v01 axis_v02 axis_v03 axis_v04 axis_v05)
PLANE_EXPS=(plane_v00 plane_v01 plane_v02 plane_v03 plane_v04 plane_v05)

total=0

delete_or_show() {
    local f="$1"
    if [ -f "$f" ]; then
        $DRY_RUN || rm "$f"
        ((total++))
        ((exp_count++))
    fi
}

process_type() {
    local sym_type=$1
    shift
    local exps=("$@")
    local sym_dir="$RENDERS/$sym_type"

    for EXP in "${exps[@]}"; do
        local exp_count=0
        # 1. Per-object root: predicted_symmetry_<EXP>.json
        for obj_dir in "$sym_dir"/*/; do
            delete_or_show "${obj_dir}predicted_symmetry_${EXP}.json"
        done

        # 2. Per-object/size/lighting: molmo_multiview_<EXP>.json + mapped_points_3d_<EXP>.json
        for obj_dir in "$sym_dir"/*/; do
            for size_dir in "$obj_dir"*/; do
                for light_dir in "$size_dir"*/; do
                    delete_or_show "${light_dir}molmo_multiview_${EXP}.json"
                    delete_or_show "${light_dir}mapped_points_3d_${EXP}.json"
                done
            done
        done

        # 3. Symmetry root: eval_*_<EXP>_<method>_results.json + summary.csv
        for f in "$sym_dir"/eval_*_${EXP}_*.json "$sym_dir"/eval_*_${EXP}_*.csv; do
            delete_or_show "$f"
        done

        echo "  $sym_type / $EXP : $exp_count files"
    done
}

if $DRY_RUN; then
    echo "DRY RUN — no files will be deleted. Run with --delete to execute."
else
    echo "DELETING files..."
fi

process_type "axis_sym"  "${AXIS_EXPS[@]}"
process_type "plane_sym" "${PLANE_EXPS[@]}"

echo ""
echo "══════════════════════════════════════════"
if $DRY_RUN; then
    echo "  Total files that WOULD be deleted: $total"
    echo "  Run with --delete to execute."
else
    echo "  Total files deleted: $total"
fi
echo "══════════════════════════════════════════"
